<main class="container book-public"><header class="book-public-head"><span>سراديب</span><h1>إصدارات سراديب</h1><p>بين صفحات الكتب تولد عوالم جديدة، ومن أقلام كتّاب سراديب تصلكم حكايات تستحق أن تُقرأ.</p></header>
<form method="get" action="/books" class="book-filters"><label>ابحث عن كتاب أو كاتب<input name="q" value="<?=e($search)?>" maxlength="100"></label><label>التصنيف<select name="genre"><option value="">جميع التصنيفات</option><?php foreach($genres as $g):?><option value="<?=e($g['genre'])?>" <?=$genre===$g['genre']?'selected':''?>><?=e($g['genre'])?></option><?php endforeach;?></select></label><label>الكاتب<select name="author"><option value="">جميع الكتّاب</option><?php foreach($authors as $a):?><option value="<?=(int)$a['id']?>" <?=$authorId===(int)$a['id']?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><button class="btn btn-primary">بحث</button></form>
<?php if(!$books):?><p>لا توجد نتائج مطابقة للبحث.</p><?php else:?><div class="book-grid"><?php foreach($books as $b):?><article class="book-card"><a href="/books/<?=e($b['slug'])?>"><img src="<?=e($b['front_cover'])?>" alt="غلاف <?=e($b['title'])?>" loading="lazy"><h2><?=e($b['title'])?></h2></a><a class="book-author" href="<?=e(writer_url($b['username'],$locale))?>"><?=e($b['author_name'])?></a><?php if($b['genre']):?><span class="book-genre"><?=e($b['genre'])?></span><?php endif;?><p><?=e(mb_strimwidth(strip_tags((string)$b['description']),0,180,'…','UTF-8'))?></p><a class="btn btn-ghost" href="/books/<?=e($b['slug'])?>">تفاصيل الكتاب</a></article><?php endforeach;?></div><?php endif;?></main>
<?php if($page>1||$hasMore): $params=['q'=>$search,'genre'=>$genre,'author'=>$authorId]; ?><nav class="book-pagination" aria-label="صفحات الكتب"><?php if($page>1):?><a class="btn btn-ghost" href="/books?<?=e(http_build_query($params+['page'=>$page-1]))?>">الصفحة السابقة</a><?php endif;?><?php if($hasMore):?><a class="btn btn-ghost" href="/books?<?=e(http_build_query($params+['page'=>$page+1]))?>">الصفحة التالية</a><?php endif;?></nav><?php endif; ?>
